//! The codebook formats IQ2_XXS, IQ2_XS, IQ3_XXS and IQ4_XS.
//!
//! IQ2_XXS, IQ2_XS and IQ3_XXS store each group of eight or four magnitudes as an
//! index into a fixed codebook, with a sign pattern per group of eight;
//! IQ4_XS maps 4-bit codes through a fixed non-linear table. The codebooks
//! are part of each format's definition, and every kernel reads them from
//! here.

use half::f16;

pub use crate::grids::IQ4NL_VALUES;

/// Magnitudes an IQ2_XXS or IQ2_XS codebook entry is made of.
const IQ2_LEVELS: [u8; 3] = [8, 25, 43];

/// Magnitudes an IQ3_XXS codebook entry is made of.
const IQ3_LEVELS: [u8; 8] = [4, 12, 20, 28, 36, 44, 52, 62];

/// The IQ2_XXS codebook: 256 groups of eight magnitudes.
pub const IQ2XXS_GRID: [[u8; 8]; 256] = expand_iq2(&IQ2XXS_INDICES);

/// The IQ2_XS codebook: 512 groups of eight magnitudes.
pub const IQ2XS_GRID: [[u8; 8]; 512] = expand_iq2(&IQ2XS_INDICES);

/// The IQ3_XXS codebook: 256 groups of four magnitudes.
pub const IQ3XXS_GRID: [[u8; 4]; 256] = expand_iq3();

/// The sign bits of a group of eight from their 7-bit index: bit `j` set
/// negates value `j`, and the eighth bit makes the number of negated values
/// even.
pub const fn iq_signs(index: u8) -> u8 {
    let index = index & 0x7f;
    index | (((index.count_ones() & 1) as u8) << 7)
}

