/// Each IQ2_XXS and IQ2_XS entry packs its eight level indices two bits
/// apiece, the first value in the lowest bits.
const fn expand_iq2<const N: usize>(indices: &[u16; N]) -> [[u8; 8]; N] {
    let mut grid = [[0; 8]; N];
    let mut i = 0;
    while i < N {
        let mut j = 0;
        while j < 8 {
            grid[i][j] = IQ2_LEVELS[((indices[i] >> (2 * j)) & 3) as usize];
            j += 1;
        }
        i += 1;
    }
    grid
}

/// Each IQ3_XXS entry packs its four level indices three bits apiece.
const fn expand_iq3() -> [[u8; 4]; 256] {
    let mut grid = [[0; 4]; 256];
    let mut i = 0;
    while i < 256 {
        let mut j = 0;
        while j < 4 {
            grid[i][j] = IQ3_LEVELS[((IQ3XXS_INDICES[i] >> (3 * j)) & 7) as usize];
            j += 1;
        }
        i += 1;
    }
    grid
}

fn half(bytes: &[u8]) -> f32 {
    f16::from_le_bytes([bytes[0], bytes[1]]).to_f32()
}

fn signed(magnitude: u8, signs: u8, j: usize) -> f32 {
    if signs >> j & 1 == 1 {
        -(magnitude as f32)
    } else {
        magnitude as f32
    }
}

// block_iq2_xxs: f16 d, u16 qs[32]. Each 32 values read two u32: four
// codebook indices, then four 7-bit sign indices and a 4-bit scale on top.
pub(crate) fn iq2_xxs_block(src: &[u8], dst: &mut [f32]) {
    let d = half(src);
    for (b, out) in dst.chunks_exact_mut(32).enumerate() {
        let at = 2 + 8 * b;
        let a = u32::from_le_bytes(src[at + 4..at + 8].try_into().unwrap());
        let db = d * (0.5 + (a >> 28) as f32) * 0.25;
        for (l, out) in out.chunks_exact_mut(8).enumerate() {
            let grid = &IQ2XXS_GRID[src[at + l] as usize];
            let signs = iq_signs((a >> (7 * l)) as u8);
            for (j, y) in out.iter_mut().enumerate() {
                *y = db * signed(grid[j], signs, j);
            }
        }
    }
}

// block_iq2_xs: f16 d, u16 qs[32], u8 scales[8]. Each 32 values have two
// 4-bit scales, one per 16; each u16 holds a 9-bit codebook index and a
// 7-bit sign index for eight values.
pub(crate) fn iq2_xs_block(src: &[u8], dst: &mut [f32]) {
    let d = half(src);
    let qs = &src[2..66];
    let scales = &src[66..74];
    for (g, out) in dst.chunks_exact_mut(8).enumerate() {
        let scale = scales[g / 4] >> (4 * (g / 2 % 2)) & 0xf;
        let db = d * (0.5 + scale as f32) * 0.25;
        let q = u16::from_le_bytes([qs[2 * g], qs[2 * g + 1]]);
        let grid = &IQ2XS_GRID[(q & 511) as usize];
        let signs = iq_signs((q >> 9) as u8);
        for (j, y) in out.iter_mut().enumerate() {
            *y = db * signed(grid[j], signs, j);
        }
    }
}

// block_iq3_xxs: f16 d, u8 qs[64], u32 scales_and_signs[8]. Each 32 values
// read eight codebook indices from qs and one u32 holding four 7-bit sign
// indices and a 4-bit scale on top.
pub(crate) fn iq3_xxs_block(src: &[u8], dst: &mut [f32]) {
    let d = half(src);
    let qs = &src[2..66];
    let aux = &src[66..98];
    for (b, out) in dst.chunks_exact_mut(32).enumerate() {
        let a = u32::from_le_bytes(aux[4 * b..4 * b + 4].try_into().unwrap());
        let db = d * (0.5 + (a >> 28) as f32) * 0.5;
        for (l, out) in out.chunks_exact_mut(8).enumerate() {
            let signs = iq_signs((a >> (7 * l)) as u8);
            let lo = &IQ3XXS_GRID[qs[8 * b + 2 * l] as usize];
            let hi = &IQ3XXS_GRID[qs[8 * b + 2 * l + 1] as usize];
            for j in 0..4 {
                out[j] = db * signed(lo[j], signs, j);
                out[j + 4] = db * signed(hi[j], signs, j + 4);
            }
        }
    }
}

// block_iq4_xs: f16 d, u16 scales_h, u8 scales_l[4], u8 qs[128]. Each 32
// values have a 6-bit scale (low four bits in scales_l, high two in
// scales_h) offset by 32; their 16 bytes hold the first 16 codes in the low
// nibbles and the next 16 in the high ones.
pub(crate) fn iq4_xs_block(src: &[u8], dst: &mut [f32]) {
    let d = half(src);
    let scales_h = u16::from_le_bytes([src[2], src[3]]);
    let scales_l = &src[4..8];
    let qs = &src[8..136];
    for (b, out) in dst.chunks_exact_mut(32).enumerate() {
        let lo = scales_l[b / 2] >> (4 * (b % 2)) & 0xf;
        let hi = (scales_h >> (2 * b) & 3) as u8;
        let dl = d * ((lo | hi << 4) as i32 - 32) as f32;
        for (j, &q) in qs[16 * b..16 * b + 16].iter().enumerate() {
            out[j] = dl * IQ4NL_VALUES[(q & 0xf) as usize] as f32;
            out[j + 16] = dl * IQ4NL_VALUES[(q >> 4) as usize] as f32;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn codebooks_expand_to_the_published_entries() {
        let le8 = |v: u64| v.to_le_bytes();
        assert_eq!(IQ2XXS_GRID[0], le8(0x0808080808080808));
        assert_eq!(IQ2XXS_GRID[7], le8(0x08080808082b0808));
        assert_eq!(IQ2XXS_GRID[255], le8(0x2b2b2b1908081908));
        assert_eq!(IQ2XS_GRID[0], le8(0x0808080808080808));
        assert_eq!(IQ2XS_GRID[1], le8(0x080808080808082b));
        assert_eq!(IQ2XS_GRID[7], le8(0x080808080819192b));
        assert_eq!(IQ2XS_GRID[511], le8(0x2b2b2b2b2b2b2b2b));
        assert_eq!(IQ3XXS_GRID[0], 0x04040404u32.to_le_bytes());
        assert_eq!(IQ3XXS_GRID[5], 0x04040c3eu32.to_le_bytes());
        assert_eq!(IQ3XXS_GRID[255], 0x3e341c04u32.to_le_bytes());
    }

    #[test]
    fn sign_patterns_have_even_parity() {
        for i in 0..128u8 {
            let s = iq_signs(i);
            assert_eq!(s & 0x7f, i);
            assert_eq!(s.count_ones() % 2, 0);
        }
    }

    fn with_scale(block: &mut [u8], d: f32) {
        block[..2].copy_from_slice(&f16::from_f32(d).to_le_bytes());
    }

    #[test]
    fn iq2_xxs_block_layout() {
        let mut block = [0u8; 66];
        with_scale(&mut block, 2.0);
        // Values 8..16 use entry 7; sign index 3 negates values 0 and 1.
        block[3] = 7;
        block[6..10].copy_from_slice(&(5u32 << 28 | 3 << 7).to_le_bytes());
        let mut out = [0.0; 256];
        iq2_xxs_block(&block, &mut out);
        let db = 2.0 * 5.5 * 0.25;
        assert_eq!(out[0], db * 8.0);
        assert_eq!(&out[8..11], &[-db * 8.0, -db * 8.0, db * 43.0]);
    }

    #[test]
    fn iq2_xs_block_layout() {
        let mut block = [0u8; 74];
        with_scale(&mut block, 2.0);
        // Group 1: entry 1 with sign index 1, which negates value 0 and,
        // for even parity, value 7.
        block[4..6].copy_from_slice(&(1u16 | 1 << 9).to_le_bytes());
        block[66] = 0x31;
        let mut out = [0.0; 256];
        iq2_xs_block(&block, &mut out);
        let (lo, hi) = (2.0 * 1.5 * 0.25, 2.0 * 3.5 * 0.25);
        assert_eq!(out[0], lo * 8.0);
        assert_eq!(out[8], -lo * 43.0);
        assert_eq!(out[15], -lo * 8.0);
        assert_eq!(out[16], hi * 8.0);
    }

    #[test]
    fn iq3_xxs_block_layout() {
        let mut block = [0u8; 98];
        with_scale(&mut block, 1.0);
        block[2] = 5;
        block[66..70].copy_from_slice(&(3u32 << 28 | 1).to_le_bytes());
        let mut out = [0.0; 256];
        iq3_xxs_block(&block, &mut out);
        let db = 3.5 * 0.5;
        assert_eq!(&out[..4], &[-db * 62.0, db * 12.0, db * 4.0, db * 4.0]);
        assert_eq!(out[7], -db * 4.0);
    }

    #[test]
    fn iq4_xs_block_layout() {
        let mut block = [0u8; 136];
        with_scale(&mut block, 0.5);
        block[2..4].copy_from_slice(&0b0100u16.to_le_bytes());
        block[4] = 0x7a;
        block[8] = 0xf0;
        block[24] = 0x01;
        let mut out = [0.0; 256];
        iq4_xs_block(&block, &mut out);
        assert_eq!(out[0], 0.5 * (10.0 - 32.0) * -127.0);
        assert_eq!(out[16], 0.5 * (10.0 - 32.0) * 113.0);
        assert_eq!(out[32], 0.5 * (23.0 - 32.0) * -104.0);
    }
}
